#include "../command_input.h"
#include "../runtime.h"
#include <cstdio>
#include <stdexcept>
namespace {unsigned checks;void check(bool value,const char *reason){++checks;if(!value){std::fprintf(stderr,"FAILED: %s\n",reason);std::fflush(stderr);throw std::runtime_error(reason);}}}
int runCommandInputTests(){using namespace Snatcher;CommandInput input;std::string error;std::vector<uint16_t> refs={410,559,535};
 check(input.open(refs,false,0,error)&&input.selectedReference()==410,"original first-menu identities");
 check(input.setButton(kCommandDown,true,error),"direction key down");CommandResponse r=input.update(10);check(r.kind==kCommandSelectionChanged&&r.reference==559,"down moves once by original identity");
 check(input.setButton(kCommandDown,true,error)&&input.update(11).kind==kCommandNoResponse&&input.selectedReference()==559,"OS key repeat cannot create a fresh edge");
 for(unsigned tick=12;tick<42;++tick)check(input.update(uint8_t(tick)).kind==kCommandNoResponse,"original initial hold interval");
 r=input.update(42);check(r.kind==kCommandSelectionChanged&&r.reference==535,"held repeat uses original low5 anchor equality");
 for(unsigned tick=43;tick<58;++tick)check(input.update(uint8_t(tick)).kind==kCommandNoResponse,"original subsequent hold interval");
 r=input.update(58);check(r.kind==kCommandSelectionChanged&&r.reference==410,"held repeat low4 cadence wraps list");
 check(input.setButton(kCommandDown,false,error)&&input.setButton(kCommandUp,true,error),"release then opposing edge");r=input.update(59);check(r.kind==kCommandSelectionChanged&&r.reference==535,"up wraps backwards");
 check(input.setButton(kCommandUp,false,error)&&input.setButton(kCommandConfirm,true,error),"confirmation edge");r=input.update(60);check(r.kind==kCommandConfirmed&&r.reference==535&&!input.active(),"confirmation resolves original reference once");
 for(unsigned tick=61;tick<255;++tick)check(input.update(uint8_t(tick)).kind==kCommandNoResponse,"resolved menu cannot duplicate completion");
 check(input.open(refs,false,1,error)&&input.selectedReference()==559,"top-level remembered ordinal is presentation state only");
 check(input.update(255).kind==kCommandNoResponse&&input.setButton(kCommandConfirm,true,error)&&input.update(0).kind==kCommandNoResponse,"held confirm cannot activate newly opened menu");
 check(input.setButton(kCommandConfirm,false,error)&&input.setButton(kCommandConfirm,true,error)&&input.update(1).kind==kCommandConfirmed,"fresh release/press accepts next context");
 check(input.setButton(kCommandConfirm,false,error)&&input.open(refs,true,2,error)&&input.selectedReference()==410,"nested context starts at original first command");
 check(input.setButton(kCommandCancel,true,error)&&input.update(2).kind==kCommandCancelled,"selected-path cancel produces once-only back response");
 check(input.setButton(kCommandCancel,false,error)&&input.open(refs,false,99,error)&&input.selectedReference()==410,"unavailable remembered index resets to first");
 check(input.setButton(kCommandCancel,true,error)&&input.update(3).kind==kCommandNoResponse&&input.active(),"root context cannot cancel without selected path");
 check(input.setButton(kCommandCancel,false,error)&&input.setButton(kCommandDown,true,error)&&input.setButton(kCommandConfirm,true,error),"combined press");r=input.update(4);check(r.kind==kCommandNoResponse&&input.selectedReference()==410,"combined directional/confirm mask is not two activations");
 check(input.setButton(kCommandDown,false,error)&&input.setButton(kCommandConfirm,false,error)&&input.setButton(kCommandLeft,true,error),"left edge");check(input.update(5).reference==535,"left follows source previous mapping");
 check(input.setButton(kCommandLeft,false,error)&&input.setButton(kCommandRight,true,error)&&input.update(6).reference==410,"right follows source next mapping");
 check(!input.setButton(CommandButton(64),true,error)&&input.active(),"unknown platform action rejected");
 std::vector<uint16_t> nine(9,1);check(!input.open(nine,false,0,error)&&input.references()==refs,"more than two source pages leaves current state intact");check(!input.open({},false,0,error),"empty command context rejects");input.close();
 CommandInput paged;std::vector<uint16_t> pageRefs={1,2,3,4,5,6,7,8};check(paged.open(pageRefs,false,7,error)&&paged.selectedIndex()==7,"source two-page menu remembers global identity index");check(paged.setButton(kCommandDown,true,error)&&paged.update(0).kind==kCommandSelectionChanged&&paged.selectedIndex()==0,"source global navigation wraps across page arrows without selecting arrows");
 check(input.setButton(kCommandRight,false,error)&&input.open({42},false,0,error)&&input.setButton(kCommandDown,true,error)&&input.update(7).kind==kCommandNoResponse&&input.selectedReference()==42,"single command ignores directions");
 input.setButton(kCommandDown,false,error);input.setButton(kCommandConfirm,true,error);check(input.update(8).kind==kCommandConfirmed,"single command still accepts confirm");
 // Release/press navigates immediately for every allowed standard-list extent.
 for(unsigned count=2;count<=7;++count){std::vector<uint16_t> values;for(unsigned i=0;i<count;++i)values.push_back(uint16_t(100+i));input.setButton(kCommandConfirm,false,error);check(input.open(values,false,0,error),"standard list extent");for(unsigned i=0;i<count*2;++i){input.setButton(kCommandDown,false,error);input.setButton(kCommandDown,true,error);r=input.update(uint8_t(i));check(r.reference==100+(i+1)%count,"standard navigation preserves semantic identities");}input.setButton(kCommandDown,false,error);}
 // Identity lookup rejects aliases and unavailable commands transactionally.
 std::vector<Scenario> scenarios(39);std::vector<uint8_t> code={0x30,0x25,0x38,0,7,0x14,0,0,0x27,0x38,0,7,0x14,0,1};Scenario scenario;check(parseScenario(code.data(),code.size(),scenario,error),"duplicate-choice grammar");scenarios[0]=scenario;EventScheduler events;SemanticTrace trace;NarrativeRuntime runtime(scenarios,events,trace);
 check(runtime.start(Cursor(57,0),std::vector<uint8_t>(352,0),error)&&runtime.run()==kRuntimeChoices,"duplicate-choice context");check(!runtime.chooseReference(7,error)&&runtime.control().selectedPath().empty()&&runtime.status()==kRuntimeChoices,"ambiguous reference never picks an arbitrary branch");check(!runtime.chooseReference(99,error)&&runtime.control().selectedPath().empty(),"unavailable reference leaves context unchanged");
 code={0x30,0x27,0x38,0,7,0x14,0,0};check(parseScenario(code.data(),code.size(),scenarios[0],error)&&runtime.start(Cursor(57,0),std::vector<uint8_t>(352,0),error)&&runtime.run()==kRuntimeChoices,"unique-choice context");events.pause(true);check(!runtime.chooseReference(7,error),"paused semantic choice rejected");events.pause(false);uint16_t selectedValue=0;check(runtime.chooseReference(7,error)&&runtime.run()==kRuntimePassFinished&&readPacked(runtime.packed(),0,selectedValue,error)&&selectedValue==1,"semantic identity dispatches original scenario state update");
 CommandInput paused;check(paused.open(refs,false,1,error)&&paused.setButton(kCommandConfirm,true,error),"paused input context");paused.discardPressed();check(paused.update(42).kind==kCommandNoResponse&&paused.selectedReference()==559,"paused edge cannot replay on resume");paused.setButton(kCommandConfirm,false,error);paused.setButton(kCommandConfirm,true,error);check(paused.update(43).kind==kCommandConfirmed,"fresh edge after pause remains accepted");
 CommandInput semantic;check(!semantic.submit(kCommandConfirm,error),"inactive semantic activation rejected");check(semantic.open(refs,true,0,error)&&!semantic.submit(kCommandDown,error),"semantic submission cannot invent direction edges");
 check(semantic.setButton(kCommandConfirm,true,error),"physical confirm is held");semantic.discardPressed();check(semantic.select(1,error)&&semantic.submit(kCommandConfirm,error)&&semantic.update(50).kind==kCommandConfirmed,"semantic mouse confirm consumes intended selected owner");
 check(semantic.open(refs,true,0,error)&&semantic.setButton(kCommandConfirm,true,error)&&semantic.update(51).kind==kCommandNoResponse,"semantic confirm preserved original physical hold across next menu");check(semantic.setButton(kCommandConfirm,false,error)&&semantic.setButton(kCommandConfirm,true,error)&&semantic.update(52).kind==kCommandConfirmed,"physical release and fresh confirm still work");semantic.setButton(kCommandConfirm,false,error);
 check(semantic.open(refs,true,0,error)&&semantic.submit(kCommandConfirm,error)&&semantic.update(53).kind==kCommandConfirmed,"unheld semantic confirm");check(semantic.open(refs,true,0,error)&&semantic.setButton(kCommandConfirm,true,error)&&semantic.update(54).kind==kCommandConfirmed,"semantic confirm never creates a phantom physical hold");semantic.setButton(kCommandConfirm,false,error);
 check(semantic.open(refs,true,0,error)&&semantic.setButton(kCommandCancel,true,error),"physical cancel held");semantic.discardPressed();check(semantic.submit(kCommandCancel,error)&&semantic.update(55).kind==kCommandCancelled,"semantic cancellation uses existing cancel gate");check(semantic.open(refs,true,0,error)&&semantic.setButton(kCommandCancel,true,error)&&semantic.update(56).kind==kCommandNoResponse,"semantic cancellation preserves physical cancel hold");check(semantic.setButton(kCommandCancel,false,error)&&semantic.setButton(kCommandCancel,true,error)&&semantic.update(57).kind==kCommandCancelled,"fresh physical cancel after release");semantic.setButton(kCommandCancel,false,error);
 check(semantic.open(refs,false,0,error)&&semantic.submit(kCommandCancel,error)&&semantic.update(58).kind==kCommandNoResponse&&semantic.active(),"uncancellable owner remains authoritative for semantic cancellation");
 std::printf("command input contracts: %u checks, 0 failures\n",checks);return 0;
}

int main(){try{return runCommandInputTests();}catch(const std::exception& e){std::fprintf(stderr,"command input test failure: %s\n",e.what());return 1;}}
